                                  color: '#16a34a',
                                  border: '1px solid #86efac',
                                  borderRadius: '10px',
                                  padding: '0 8px',
                                  height: '32px',
                                  display: 'flex',
                                  alignItems: 'center',
                                  gap: '4px',
                                  fontSize: '0.70rem',
                                  fontWeight: 800,
                                  cursor: 'pointer',
                                  transition: 'background 0.2s',
                                  whiteSpace: 'nowrap'
