                                  background: '#f8fafc',
                                  border: '1px solid #e2e8f0',
                                  borderRadius: '20px',
                                  padding: '8px 16px',
                                  fontSize: '0.82rem',
                                  fontWeight: 800,
                                  color: '#0f172a',
                                  cursor: 'pointer',
                                  display: 'flex',
                                  alignItems: 'center',
                                  gap: '6px',
                                  transition: 'all 0.15s ease',
                                  boxShadow: '0 2px 6px rgba(0,0,0,0.02)'
